={
  "model": "qwen2.5:7b",
  "stream": false,
  "prompt": "Format this raw client reply into a polished 2-3 sentence testimonial quote. Keep their actual words/meaning, just tighten grammar and flow. Raw reply: {{$json.body.text}}\n\nReturn ONLY JSON with key: polished_quote."
}

={
  "jsonrpc": "2.0", "method": "call",
  "params": {
    "service": "object", "method": "execute_kw",
    "args": ["{{$env.ODOO_DB}}", {{$env.ODOO_UID}}, "{{$env.ODOO_API_KEY}}",
      "mail.channel", "message_post",
      [ [{{$env.ODOO_DISCUSS_CHANNEL_ID}}], {
        "body": {{JSON.stringify('New draft testimonial ready for client sign-off before publishing: ' + $json.polished_quote)}}
      } ]
  }, "id": 1
}
